local _, addon = ...
addon.localeData.deDE.ambient = {
    GNOME = { "Mein Schild ist nicht zu klein. Die Welt ist einfach unvernünftig skaliert.", "*holt einen winzigen Schraubenschlüssel aus dem Handschuh und zieht eine Mutter nach.*", "Wenn die Konstruktion knarzt, ist das kein Fehler. Das ist Rückmeldung.", "*versucht, eine Delle im Helm millimetergenau auszumessen.*", "Ein Plan ist erst vollständig, wenn jemand lautstark dagegenrennt.", "*schreibt eine Zahl auf den Schildrand und radiert sie sofort wieder aus.*", "An meiner Rüstung ist alles Absicht. Besonders das, was noch brennt.", "*klopft zweimal gegen einen kleinen, selbstgebauten Warnsummer.*" },
    HUMAN = { "Die Stille vor dem Kampf ist schlimmer als der Lärm danach.", "*fährt mit dem Finger über das verblichene Wappen auf dem Schild.*", "Wer hier neben mir steht, geht auch neben mir nach Hause.", "*prüft noch einmal die Riemen eines Kameraden.*", "Ein Schlachtplan ist nur Papier, bis jemand den ersten Schritt macht.", "*richtet die Reihen mit einem kurzen Blick und einer Handbewegung aus.*", "Mein Vater sagte immer: Sei mutig. Meine Mutter: Komm lebend zurück.", "*zieht die Handschuhe straffer und sieht zum Horizont.*" },
    DWARF = { "Ein Krieger ohne Bart hat keine Ausrede, so langsam zu sein.", "*fischt einen Krümel Brot aus dem Bart und betrachtet ihn misstrauisch.*", "Den letzten Kampf hab ich gewonnen. Den letzten Humpen leider nicht.", "*poliert eine Scharte in der Axt, bis sie nur noch halb so gefährlich aussieht.*", "Wer behauptet, Zwerge seien stur, hat noch nie mit einem Berg verhandelt.", "*rüttelt am Schildriemen und murmelt etwas über billige Handwerkskunst.*", "Wenn wir überleben, spendier ich einen. Wenn nicht, ist das Bier verschwendet.", "*lauscht prüfend, ob im Rucksack noch eine Flasche klirrt.*" },
    NIGHTELF = { "Manche Bäume, die ich kannte, waren alt, bevor dieses Königreich einen Namen hatte.", "*fährt über eine Blattgravur am Waffenknauf.*", "Das Blut vergeht. Die Erinnerung an den Grund des Kampfes bleibt.", "*hält einen Augenblick inne und lauscht den Geräuschen des Waldes.*", "Ein stiller Schritt kann mehr bewahren als ein lauter Sieg.", "*nimmt vorsichtig ein Blatt vom Schulterpanzer und lässt es frei.*", "Heute ist die Nacht nicht still. Ich werde sie trotzdem achten.", "*blickt lange in das letzte Licht zwischen den Bäumen.*" },
    DRAENEI = { "Ich habe schon einmal ein Zuhause verloren. Ein zweites gebe ich nicht leicht auf.", "*streicht mit der Hand über ein kleines Zeichen der Erinnerung.*", "Man muss die Hoffnung nicht schreien, um sie zu tragen.", "*ordnet den Schild so, dass hinter ihm noch jemand Platz findet.*", "Manchmal ist Mut nichts weiter als der nächste Schritt trotz der Furcht.", "*schließt kurz die Augen und sammelt die Gedanken.*", "Wer Schutz sucht, soll hinter mir nicht auf die Knie fallen müssen.", "*prüft vorsichtig die Schneide, ohne den Blick von den Verbündeten zu nehmen.*" },
    ORC = { "Die Ahnen fragen nicht, wie laut ich gebrüllt habe. Sie fragen, wen ich beschützt habe.", "*reibt einen alten Clananhänger zwischen Daumen und Zeigefinger.*", "Eine scharfe Klinge braucht keine große Geschichte. Die Geschichte kommt danach.", "*zieht die Lederwicklung am Axtstiel fest.*", "Ich ehre meinen Clan nicht, indem ich jeden Streit anfange.", "*blickt über die Schulter, ob die Gefährten noch folgen.*", "Wer hinter mir steht, ist mein Grund, vorwärtszugehen.", "*schlägt sich einmal gegen die Brust und hebt das Kinn.*" },
    TROLL = { "Wenn die Loa schon zuschauen, will ich wenigstens gut aussehen, heh.", "*legt zwei kleine Knochenperlen auf die Handfläche und zählt sie nach.*", "Der alte Hexendoktor meinte, meine Zukunft sei gefährlich. Sehr hilfreich, mon.", "*klopft einen schnellen Trommelrhythmus mit den Fingern auf den Schild.*", "Die Ahnen erzählen Geschichten. Ich liefere ihnen neue.", "*neigt den Kopf, als höre er eine ferne Trommel.*", "Wenn mein Plan scheitert, war es ein besonders mutiger Versuch.", "*steckt einen losen Talisman wieder unter die Rüstung.*" },
    TAUREN = { "Ein Berg spricht wenig. Trotzdem versteht jeder, wenn er sich bewegt.", "*drückt einen Huf langsam in den Boden und prüft den Halt.*", "Ich kämpfe, damit andere die Ruhe der Ebene noch erleben.", "*streicht mit den Fingern über ein geflochtenes Erinnerungsband.*", "Die Erdenmutter fordert keinen Ruhm. Nur Verantwortung.", "*blickt zum Himmel und atmet tief durch die Nüstern.*", "Wer die Kraft besitzt, zu warten, weiß auch, wann sie gebraucht wird.", "*legt einen flachen Stein sorgfältig zurück an seinen Platz.*" },
    UNDEAD = { "Ich habe schon schlechter ausgesehen. Vor meinem Tod allerdings selten.", "*schiebt einen Fingerknochen wieder in den Handschuh.*", "Der letzte Heiler hat mich für hoffnungslos erklärt. Netter Kerl.", "*prüft mit trockenem Knacken den Halt des Schultergelenks.*", "Ich schlafe schlecht. Das ist seit meiner Beerdigung keine Neuigkeit.", "*wischt Erde von einer alten Rüstungsschnalle.*", "Wer den Tod gesehen hat, sollte wenigstens einen Sinn für Humor behalten.", "*zieht mit einem knappen, knarrenden Laut die Mundwinkel hoch.*" },
    BLOODELF = { "Auch ein Schlachtfeld verdient eine gewisse Ästhetik. Es bekommt sie nur selten.", "*streicht eine Falte aus einem fein bestickten Ärmel.*", "Ein Schwert ist kein Schmuckstück. Das heißt nicht, dass es hässlich sein muss.", "*stellt einen Handschutz mit winziger Bewegung korrekt ein.*", "Meine Ahnen hätten über meine Rüstung gestritten. Über meinen Mut wohl nicht.", "*betrachtet abschätzig eine Delle im Schulterpanzer.*", "Ich habe für diesen Mantel bezahlt. Der Feind tut gut daran, Abstand zu halten.", "*schiebt eine lose Haarsträhne aus dem Gesicht und setzt den Helm sorgfältig auf.*" },
    NEUTRAL = { "Nach dem Kampf erzählen alle vom Sieg. Vorher zählt nur, wer stehen bleibt.", "*prüft die Schneide und steckt die Waffe wieder ruhig weg.*", "Der nächste Schritt ist leichter, wenn man weiß, für wen man ihn tut.", "*setzt den Helm ein wenig tiefer und strafft die Schultern.*", "Ein Schild schützt nur so gut wie die Hand, die ihn hält.", "*lässt den Blick langsam über die Reihen der Verbündeten wandern.*", "Mut ist keine Abwesenheit von Angst. Er ist eine Entscheidung.", "*schließt die Faust um den Griff und atmet langsam aus.*" },
}
